# Runs independently of Codex. Install the XML generated by task-scheduler.ps1.
$ErrorActionPreference = 'Stop'
$repo = Split-Path -Parent $PSScriptRoot
$python = Join-Path $repo '.venv\Scripts\python.exe'
if (-not (Test-Path -LiteralPath $python -PathType Leaf)) { throw 'Project Python is missing' }
Push-Location -LiteralPath $repo
try {
    & $python -m src.registry_sync
    $result = $LASTEXITCODE
    if ($result -ne 0) { throw "Registry refresh failed (exit $result); inspect runtime/registry" }
} finally { Pop-Location }
